// This is file of your component
// You can use any dependencies from npm; we import them automatically in package.json

"use client";

import * as React from "react";
import { cn } from "@/lib/utils";



/* ------------------------------------------------------------------ */
/* Types                                                               */
/* ------------------------------------------------------------------ */

export interface HeroAction {
  label: string;
  /** Renders a link when provided, otherwise a button. */
  href?: string;
  onClick?: () => void;
}

export interface CodeTab {
  /** Text on the tab, e.g. "cURL". */
  label: string;
  /** Drives the syntax colours: bash, curl, typescript, javascript, python... */
  language: string;
  code: string;
}

export interface SplitDeveloperHeroProps {
  /** Small status pill above the headline. */
  badge?: string;
  title: React.ReactNode;
  description: string;
  primaryAction: HeroAction;
  secondaryAction?: HeroAction;
  codeTabs: CodeTab[];
  className?: string;
}



/* ------------------------------------------------------------------ */
/* Tiny syntax highlighter (no library needed)                         */
/* ------------------------------------------------------------------ */

type TokenType = "string" | "comment" | "keyword" | "number" | "function" | "flag";

const TOKEN_CLASS: Record<TokenType, string> = {
  string: "text-emerald-600 dark:text-emerald-400",
  comment: "italic text-muted-foreground",
  keyword: "text-primary",
  number: "text-amber-600 dark:text-amber-400",
  function: "text-sky-600 dark:text-sky-400",
  flag: "text-sky-600 dark:text-sky-400",
};

const KEYWORDS =
  "const|let|var|await|async|import|from|export|default|function|return|new|class|if|else|for|of|in|as|def|print|with|try|except|raise|lambda|yield|True|False|None|true|false|null|undefined";

const TOKEN_ORDER: TokenType[] = ["string", "comment", "keyword", "number", "function", "flag"];

// One regular expression per language family: strings first, so a // inside a URL is never read as a comment
function buildPattern(language: string) {
  const shell = /^(bash|shell|sh|curl|zsh)$/i.test(language);
  const hashComments = shell || /^(python|py|ruby|yaml|yml)$/i.test(language);
  return new RegExp(
    [
      `("(?:[^"\\\\]|\\\\.)*"|'(?:[^'\\\\]|\\\\.)*'|\`(?:[^\`\\\\]|\\\\.)*\`)`, // 1 strings
      hashComments ? "(#.*)" : "(\\/\\/.*)",                                       // 2 comments
      `\\b(${KEYWORDS})\\b`,                                                         // 3 keywords
      "(\\b\\d+(?:\\.\\d+)?\\b)",                                                    // 4 numbers
      "(\\b[A-Za-z_]\\w*(?=\\())",                                                   // 5 function calls
      shell ? "((?<=\\s)--?[A-Za-z][\\w-]*)" : "(?!)",                               // 6 command line flags
    ].join("|"),
    "g"
  );
}

function highlight(line: string, language: string): React.ReactNode[] {
  const pattern = buildPattern(language);
  const out: React.ReactNode[] = [];
  let last = 0;
  let match: RegExpExecArray | null;

  while ((match = pattern.exec(line)) !== null) {
    if (match[0] === "") { pattern.lastIndex++; continue; }
    if (match.index > last) out.push(line.slice(last, match.index));
    const type = TOKEN_ORDER[match.findIndex((g, i) => i > 0 && g !== undefined) - 1];
    out.push(<span key={match.index} className={TOKEN_CLASS[type]}>{match[0]}</span>);
    last = match.index + match[0].length;
  }
  if (last < line.length) out.push(line.slice(last));
  return out;
}



/* ------------------------------------------------------------------ */
/* Copy button with a self-drawing checkmark                           */
/* ------------------------------------------------------------------ */

async function copyToClipboard(text: string) {
  try {
    await navigator.clipboard.writeText(text);
    return true;
  } catch {
    // Fallback for browsers or frames without clipboard access
    const area = document.createElement("textarea");
    area.value = text;
    area.style.position = "fixed";
    area.style.opacity = "0";
    document.body.appendChild(area);
    area.select();
    const ok = document.execCommand("copy");
    area.remove();
    return ok;
  }
}

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = React.useState(false);
  const timer = React.useRef<number | undefined>(undefined);

  // Forget the "copied" state when the code changes (new tab) or the component unmounts
  React.useEffect(() => {
    setCopied(false);
    return () => window.clearTimeout(timer.current);
  }, [text]);

  const handleCopy = async () => {
    if (!(await copyToClipboard(text))) return;
    setCopied(true);
    window.clearTimeout(timer.current);
    timer.current = window.setTimeout(() => setCopied(false), 1800);
  };

  return (
    <button
      type="button"
      onClick={handleCopy}
      className="group inline-flex h-8 shrink-0 items-center gap-1.5 rounded-lg border border-border bg-background/60 px-2.5 text-xs font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-accent-foreground focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
    >
      {/* The two icons are stacked and cross-fade */}
      <span className="relative size-4">
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"
          className={cn("absolute inset-0 size-4 transition-all duration-200 motion-reduce:transition-none", copied ? "scale-50 opacity-0" : "scale-100 opacity-100")}>
          <rect x="9" y="9" width="11" height="11" rx="2" />
          <path d="M5 15V6a2 2 0 0 1 2-2h9" />
        </svg>
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"
          className={cn("absolute inset-0 size-4 text-emerald-500 transition-all duration-200 motion-reduce:transition-none", copied ? "scale-100 opacity-100" : "scale-50 opacity-0")}>
          {/* The tick draws itself by animating the dash offset */}
          <path d="M5 12.5l4.5 4.5L19 7.5" style={{ strokeDasharray: 24, strokeDashoffset: copied ? 0 : 24, transition: "stroke-dashoffset 0.35s ease-out 0.05s" }} />
        </svg>
      </span>
      <span aria-live="polite" className="w-9 text-left">{copied ? "Copied" : "Copy"}</span>
    </button>
  );
}



/* ------------------------------------------------------------------ */
/* Code window with tabs                                               */
/* ------------------------------------------------------------------ */

function CodeWindow({ tabs }: { tabs: CodeTab[] }) {
  const baseId = React.useId();
  const [active, setActive] = React.useState(0);   // highlighted tab
  const [shown, setShown] = React.useState(0);     // tab whose code is on screen (lags a moment for the fade)
  const [visible, setVisible] = React.useState(true);
  const fade = React.useRef<number | undefined>(undefined);
  const tabRefs = React.useRef<(HTMLButtonElement | null)[]>([]);

  React.useEffect(() => () => window.clearTimeout(fade.current), []);

  const select = (index: number) => {
    if (index === active) return;
    setActive(index);
    setVisible(false);
    window.clearTimeout(fade.current);
    fade.current = window.setTimeout(() => { setShown(index); setVisible(true); }, 90);
  };

  // Arrow keys, Home and End move between tabs (roving tabindex)
  const handleKeyDown = (e: React.KeyboardEvent) => {
    const last = tabs.length - 1;
    const next = e.key === "ArrowRight" ? (active + 1) % tabs.length : e.key === "ArrowLeft" ? (active - 1 + tabs.length) % tabs.length : e.key === "Home" ? 0 : e.key === "End" ? last : -1;
    if (next < 0) return;
    e.preventDefault();
    select(next);
    tabRefs.current[next]?.focus();
  };

  const current = tabs[shown] ?? tabs[0];
  if (!current) return null;
  const lines = current.code.replace(/\n$/, "").split("\n");

  return (
    <div className="min-w-0 overflow-hidden rounded-2xl border border-border bg-card text-card-foreground shadow-2xl shadow-black/10 dark:shadow-black/50">
      {/* Title bar: window dots, tabs and the copy button */}
      <div className="flex items-center gap-3 border-b border-border bg-muted/40 px-4 py-2.5">
        <div className="hidden gap-1.5 sm:flex" aria-hidden="true">
          <span className="size-2.5 rounded-full bg-border" />
          <span className="size-2.5 rounded-full bg-border" />
          <span className="size-2.5 rounded-full bg-border" />
        </div>

        <div role="tablist" aria-label="Code examples" onKeyDown={handleKeyDown} className="flex min-w-0 flex-1 gap-1 overflow-x-auto">
          {tabs.map((tab, i) => (
            <button
              key={tab.label}
              ref={(el) => { tabRefs.current[i] = el; }}
              type="button"
              role="tab"
              id={`${baseId}-tab-${i}`}
              aria-selected={active === i}
              aria-controls={`${baseId}-panel`}
              tabIndex={active === i ? 0 : -1}
              onClick={() => select(i)}
              className={cn(
                "shrink-0 rounded-md px-3 py-1.5 text-xs font-medium transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring",
                active === i ? "bg-background text-foreground shadow-sm ring-1 ring-border" : "text-muted-foreground hover:text-foreground"
              )}
            >
              {tab.label}
            </button>
          ))}
        </div>

        <CopyButton text={current.code} />
      </div>

      {/* Code */}
      <div
        role="tabpanel"
        id={`${baseId}-panel`}
        aria-labelledby={`${baseId}-tab-${active}`}
        tabIndex={0}
        className={cn("overflow-x-auto p-4 font-mono text-[13px] leading-6 transition-opacity duration-150 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-ring motion-reduce:transition-none", visible ? "opacity-100" : "opacity-0")}
      >
        <pre className="w-max min-w-full">
          <code>
            {lines.map((line, i) => (
              <div key={i} className="flex">
                <span aria-hidden="true" className="w-8 shrink-0 select-none pr-4 text-right text-muted-foreground/50">{i + 1}</span>
                <span className="whitespace-pre">{line ? highlight(line, current.language) : " "}</span>
              </div>
            ))}
          </code>
        </pre>
      </div>
    </div>
  );
}



/* ------------------------------------------------------------------ */
/* Hero                                                                */
/* ------------------------------------------------------------------ */

function ActionButton({ action, variant }: { action: HeroAction; variant: "primary" | "secondary" }) {
  const classes = cn(
    "group inline-flex h-12 items-center justify-center gap-2 rounded-xl px-6 text-sm font-medium transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-background active:scale-[0.98]",
    variant === "primary"
      ? "bg-primary text-primary-foreground shadow-sm hover:opacity-90"
      : "border border-border bg-background text-foreground hover:bg-accent hover:text-accent-foreground"
  );
  const content = (
    <>
      {action.label}
      {variant === "primary" && (
        <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true" className="size-4 transition-transform group-hover:translate-x-0.5">
          <path d="M5 12h14M13 6l6 6-6 6" />
        </svg>
      )}
    </>
  );
  return action.href ? (
    <a href={action.href} onClick={action.onClick} className={classes}>{content}</a>
  ) : (
    <button type="button" onClick={action.onClick} className={classes}>{content}</button>
  );
}

export function SplitDeveloperHero({ badge, title, description, primaryAction, secondaryAction, codeTabs, className }: SplitDeveloperHeroProps) {
  return (
    <section className={cn("relative isolate overflow-hidden bg-background px-4 py-16 text-foreground sm:px-6 sm:py-24 lg:py-28", className)}>
      {/* Soft background glow */}
      <div aria-hidden="true" className="pointer-events-none absolute inset-x-0 top-0 -z-10 h-[480px] bg-[radial-gradient(60%_60%_at_50%_0%,hsl(var(--primary)/0.12),transparent)]" />

      {/* Two columns on desktop, stacked on mobile. min-w-0 lets the code window scroll instead of stretching the page */}
      <div className="mx-auto grid max-w-6xl items-center gap-12 lg:grid-cols-2 lg:gap-16">
        <div className="min-w-0 space-y-6">
          {badge && (
            <div className="inline-flex items-center gap-2 rounded-full border border-border bg-card px-3 py-1 text-xs font-medium text-muted-foreground shadow-sm">
              <span className="relative flex size-2">
                <span className="absolute inline-flex size-full animate-ping rounded-full bg-emerald-500/60 motion-reduce:animate-none" />
                <span className="relative inline-flex size-2 rounded-full bg-emerald-500" />
              </span>
              {badge}
            </div>
          )}

          <h1 className="text-balance text-4xl font-bold tracking-tight sm:text-5xl lg:text-6xl">{title}</h1>
          <p className="max-w-xl text-pretty text-base leading-7 text-muted-foreground sm:text-lg">{description}</p>

          <div className="flex flex-col gap-3 pt-2 sm:flex-row">
            <ActionButton action={primaryAction} variant="primary" />
            {secondaryAction && <ActionButton action={secondaryAction} variant="secondary" />}
          </div>
        </div>

        <div className="relative min-w-0">
          <div aria-hidden="true" className="absolute -inset-4 -z-10 rounded-[2rem] bg-gradient-to-tr from-primary/20 via-transparent to-primary/10 blur-2xl" />
          <CodeWindow tabs={codeTabs} />
        </div>
      </div>
    </section>
  );
}

